import { SETTING_SPECS, SETTING_KEYS } from './settings.mjs';

export function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const TOPICS = {
  tpm: 'TPM & equipment',
  'shift-management': 'Line & shift management',
  improvement: 'Improvement & kaizen',
  quality: 'Quality',
  safety: 'Safety & 5S',
  'open-work': 'Managing open work',
  strategy: 'Strategy & targets',
  other: 'Other'
};

export const topicLabel = (t) => TOPICS[t] ?? t;
export const topicList = () => Object.entries(TOPICS);

// The state machine stores English tokens; this is the one place a person reads them. A raw
// `awaiting_payment` on a page reads as a bug, so every status goes through a label here.
const QUESTION_STATUS = { open: 'answered from the library', routed: 'sent to a practitioner', answered: 'answered by a practitioner', closed: 'closed' };
const BOOKING_STATUS = { requested: 'waiting for the practitioner to confirm the time', awaiting_payment: 'time confirmed — waiting for your transfer', paid: 'payment received', completed: 'session completed', cancelled: 'cancelled' };
const NOTE_STATUS = { published: 'published in the library', blocked: 'blocked by the gate', draft: 'draft' };

// `open` covers both an answer and a refusal; only the coverage says which, so a refusal never claims an answer.
export const questionStatus = (s, coverage = 'ok') => (s === 'open' && coverage === 'thin' ? 'refused — the library had nothing for this' : QUESTION_STATUS[s] ?? s);

// What the page may say about a refusal: the model's own reason, with the marker stripped, or a plain fixed sentence.
export function missingReason(q) {
  const reason = String(q.ai_missing ?? '').replace(/INSUFFICIENT_DATA/g, '').trim();
  return reason || 'No note in the library answers this question closely enough to cite.';
}
export const bookingStatus = (s) => BOOKING_STATUS[s] ?? s;
export const noteStatus = (s) => NOTE_STATUS[s] ?? s;

const initialsOf = (name) =>
  String(name ?? '?')
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => w[0])
    .join('')
    .slice(0, 2)
    .toUpperCase();

const topicSlugs = (value) => {
  if (Array.isArray(value)) return value.map((t) => String(t).trim()).filter(Boolean);
  return String(value ?? '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
};

// A note card says how long the note takes to read, and leads with its first real sentence.
function readingMinutes(body) {
  const words = String(body ?? '').split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}

function summary(body) {
  // Strips the markdown rather than showing it: a card that reads "**Don't** count the number" is
  // showing its own source. markdownToText does the stripping, so the card and the page agree.
  const text = markdownToText(body);
  if (!text || text.length < 30) return 'A note written by a practitioner.';
  const first = text.split(/(?<=[.!?])\s/)[0];
  return first.length > 150 ? `${first.slice(0, 147)}…` : first;
}

